package br.com.sussmartcare.telemetry.domain; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="biometric_observations") public class BiometricObservation { @Id private UUID id; @Column(nullable=false) private UUID sessionId; @Column(nullable=false) private UUID deviceId; @Column(nullable=false) private String type; @Column(nullable=false) private Double value; private String unit; @Column(nullable=false) private Instant measuredAt; @Column(nullable=false) private String sourceContext; protected BiometricObservation(){} public BiometricObservation(UUID session,UUID device,String type,Double value,String unit,Instant at,String context){id=UUID.randomUUID();sessionId=session;deviceId=device;this.type=type;this.value=value;this.unit=unit;measuredAt=at;sourceContext=context;} public UUID getId(){return id;} public UUID getSessionId(){return sessionId;} public UUID getDeviceId(){return deviceId;} public String getType(){return type;} public Double getValue(){return value;} public String getUnit(){return unit;} public Instant getMeasuredAt(){return measuredAt;} public String getSourceContext(){return sourceContext;} }